    protected void preloadLines(TransDate _date)
    {
        // Data type = GUPPriceEngineTradeAgreementLine.
        this.lineList = this.loadAllAvailableLines(_date);

        this.loadLineExclusions(lineList, _date);

        // Key = Datasource name (table name or provider class name). Value = GUPPriceEngineDatasourceAggregationObject
        Map pricingAttributeDatasourceMapTemp = new Map(Types::String, Types::AnyType);

        ListEnumerator enumerator = lineList.getEnumerator();
        while (enumerator.moveNext())
        {
            GUPPriceEngineTradeAgreementLine line = enumerator.current();

            this.loadLineRequiredFields(line, line.parmHeaderAttribute(), pricingAttributeDatasourceMapTemp);
            
            this.loadLineRequiredFields(line, line.parmLineAttribute(), pricingAttributeDatasourceMapTemp);
        }

        this.pricingAttributeDatasourceMap = pricingAttributeDatasourceMapTemp;
    }

    /// <summary>
    /// Load all existing and posted trade agreement journal lines (no filter is applied)
    /// </summary>
    /// <param name="_date">
    /// The transaction date used to load trade agreement lines.
    /// </param>
    /// <returns>A list of all posted lines.</returns>
    private List loadAllAvailableLines(TransDate _date)
    {
        PriceDiscTable priceDiscTable;
        GUPPricingRule gupPricingRuleHeader, gupPricingRuleLine;
        GUPPricingAttributeGroup gupPricingAttributeGroupHeader, gupPricingAttributeGroupLine;

        List lineListTemp = new List(Types::AnyType);

        // Select new TradeAgreement (ruleHeader & ruleLine != 0) only.
        while select priceDiscTable
                where priceDiscTable.PriceComponentCombination != 0 &&
                      (dateNull() == priceDiscTable.FromDate || priceDiscTable.FromDate <= _date) &&
                      (dateNull() == priceDiscTable.ToDate || priceDiscTable.ToDate >= _date)
            outer join gupPricingRuleHeader
                where gupPricingRuleHeader.RECID == priceDiscTable.PricingRuleHeader
            outer join gupPricingAttributeGroupHeader
                where gupPricingRuleHeader.PRICEATTRIBUTEGROUP == gupPricingAttributeGroupHeader.RECID
            outer join gupPricingRuleLine
                where gupPricingRuleLine.RECID == priceDiscTable.PricingRuleLine
            outer join gupPricingAttributeGroupLine
                where gupPricingRuleLine.PRICEATTRIBUTEGROUP == gupPricingAttributeGroupLine.RECID
        {
            GUPPriceEngineAttributeGroupObject headerAttribute = null, lineAttribute = null;

            // Load header & line attribute group. Attribute group applies to all == null object.
            headerAttribute = this.createAttributeGroupObject(gupPricingRuleHeader, gupPricingAttributeGroupHeader);
            lineAttribute = this.createAttributeGroupObject(gupPricingRuleLine, gupPricingAttributeGroupLine);

            GUPPriceEngineTradeAgreementLine journalLine = new GUPPriceEngineTradeAgreementLine(priceDiscTable, headerAttribute, lineAttribute);
            lineListTemp.addEnd(journalLine);
        }

        return lineListTemp;
    }

    public void loadLineExclusions(List _lineList, TransDate _date)
    {
        // Key = GUPPricingRule.RecId (An unique header/line record for each TA line).
        // Value = GUPPriceEngineAttributeGroupObject
        Map pricingRuleIdMap = new Map(Types::Int64, Types::AnyType);
        
        ListEnumerator enumerator = lineList.getEnumerator();
        while (enumerator.moveNext())
        {
            GUPPriceEngineTradeAgreementLine line = enumerator.current();

            if(line.parmHeaderAttribute() != null)
            {
                GUPPricingRule pricingRule = line.parmHeaderAttribute().parmPricingRule();
                pricingRuleIdMap.add(pricingRule.recId, line.parmHeaderAttribute());
            }

            if(line.parmLineAttribute() != null)
            {
                GUPPricingRule pricingRule = line.parmLineAttribute().parmPricingRule();
                pricingRuleIdMap.add(pricingRule.recId, line.parmLineAttribute());
            }
        }

        PriceDiscTable priceDiscTable;
        GUPPricingRule gupPricingRuleHeader, gupPricingRuleLine;
        GUPPricingAttributeLineState lineExclusion;
        CustTable custTable;
        InventTable inventTable;

        // CustTable exclusion.
        while select PricingRuleHeader from priceDiscTable
                where priceDiscTable.PricingRuleHeader != 0 &&
                      (dateNull() == priceDiscTable.FromDate || priceDiscTable.FromDate <= _date) &&
                      (dateNull() == priceDiscTable.ToDate || priceDiscTable.ToDate >= _date)
            join lineExclusion
                where lineExclusion.LineType == GUPPricingAttributeLineType::Exclude
                    && lineExclusion.ParentTableId == tableNum(GUPPricingRule)
                    && lineExclusion.LineTableId == tableNum(CustTable)
                    && lineExclusion.ParentRecId == priceDiscTable.PricingRuleHeader
            join AccountNum from custTable
                where custTable.RecId == lineExclusion.LineRecId
        {
            GUPPriceEngineAttributeGroupObject attributeGroup = pricingRuleIdMap.lookup(priceDiscTable.PricingRuleHeader);
            // Refer to CustTable.AccountNum, as salesTable stores custAccount instead of custTable.recId
            attributeGroup.addExcludedId(custTable.AccountNum);
        }

        // InventTable exclusion.
        while select PricingRuleLine from priceDiscTable
                where priceDiscTable.PricingRuleLine != 0 &&
                      (dateNull() == priceDiscTable.FromDate || priceDiscTable.FromDate <= _date) &&
                      (dateNull() == priceDiscTable.ToDate || priceDiscTable.ToDate >= _date)
            join lineExclusion
                where lineExclusion.LineType == GUPPricingAttributeLineType::Exclude
                    && lineExclusion.ParentTableId == tableNum(GUPPricingRule)
                    && lineExclusion.LineTableId == tableNum(InventTable)
                    && lineExclusion.ParentRecId == priceDiscTable.PricingRuleLine
            join ItemId from inventTable
                where inventTable.RecId == lineExclusion.LineRecId
        {
            GUPPriceEngineAttributeGroupObject attributeGroup = pricingRuleIdMap.lookup(priceDiscTable.PricingRuleLine);
            // Refer to InventTable.ItemId, as salesLine stores ItemId instead of recId.
            attributeGroup.addExcludedId(inventTable.ItemId);
        }
    }
